begin;

update public.spell_catalog set name_ru='Ужасающее иссушение Аби-Дальзима', effect_summary='Высасываешь влагу из существ в 30-футовом кубе в точке в пределах 150 футов. Все цели делают спасбросок Телосложения, получая 12к8 некротического урона при провале или половину при успехе. Конструкты и нежить невосприимчивы; растения и водяные элементали совершают спасбросок с помехой.', author_description='Очень большой мгновенный некротический удар по области, особенно опасный для всего, что буквально состоит из воды или живой растительной ткани.', author_comment='Заклинание восьмого уровня, которое решает проблему полива максимально радикальным способом.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Немагические растения в области, которые не являются существами, мгновенно засыхают и погибают. Материальный компонент — кусочек губки.', material='кусочек губки — не расходуется', material_cost_gp=null, material_consumed=false, material_consumption='none' where slug='abi-dalzim-s-horrid-wilting' and source_kind='official';

update public.spell_catalog set name_ru='Тёмная звезда', effect_summary='Создаёшь сферу радиусом до 40 футов в пределах 150 футов на срок до 1 минуты с концентрацией. Внутри — магическая тьма, труднопроходимая местность и полная тишина: звук не создаётся и не проходит через область, поэтому заклинания с вербальным компонентом там невозможны. Существо, впервые за ход вошедшее в сферу или начавшее там ход, делает спасбросок Телосложения и получает 8к10 урона силовым полем при провале или половину при успехе.', author_description='Почти локальная чёрная дыра: она выключает зрение, звук и вербальную магию, одновременно перемалывая всё внутри гравитацией.', author_comment='Если поле боя стало абсолютно тёмным, тихим и начало наносить восемь к10 — это уже не просто плохое освещение.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Тёмное зрение не позволяет видеть сквозь область, немагический свет её не освещает. Существо, сведённое этим уроном до 0 хитов, дезинтегрируется вместе с немагическим снаряжением. Оникс и капля крови заклинателя расходуются.', material='осколок оникса и капля крови заклинателя — оба расходуются', material_cost_gp=null, material_consumed=true, material_consumption='always' where slug='dark-star' and source_kind='official';

update public.spell_catalog set name_ru='Священная звезда Мистры', effect_summary='Бонусным действием создаёшь рядом с собой сияющую звезду на срок до 1 минуты с концентрацией. При сотворении и бонусным действием в последующие ходы совершаешь дальнобойную атаку заклинанием по цели в пределах 120 футов; попадание наносит 4к10 + модификатор заклинательной характеристики урона силовым полем или излучением. Пока звезда существует, ты имеешь укрытие на три четверти.', author_description='Атакующая и защитная магия в одном объекте: звезда стреляет каждый раунд и одновременно превращает тебя в очень неудобную цель.', author_comment='Мистра выдала магу маленькую звезду. Маг немедленно использовал её как турель и переносную стену.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Когда успешно проходишь спасбросок против заклинания 7 уровня или ниже, которое нацелено только на тебя и не создаёт область, можешь реакцией отразить его обратно в заклинателя; тот совершает спасбросок против собственной Сл заклинаний.', casting_time='1 бонусное действие' where slug='holy-star-of-mystra' and source_kind='official';

update public.spell_catalog set name_ru='Иллюзорный дракон', effect_summary='Создаёшь Огромного теневого дракона в свободном пространстве в пределах 120 футов на срок до 1 минуты с концентрацией. Враги, увидевшие его появление, делают спасбросок Мудрости или пугаются. Бонусным действием дракон перемещается до 60 футов и по пути может выдохнуть 60-футовый конус выбранного типа урона — кислота, холод, огонь, молния, некротический или яд; цели делают спасбросок Интеллекта и получают 7к6 при провале или половину при успехе.', author_description='Иллюзия ведёт себя почти как отдельное неуязвимое чудовище: пугает, занимает место и каждый ход выдаёт большой конус урона.', author_comment='Дракон ненастоящий. Семь к6 и паника на поле боя об этом не знают.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Атаки автоматически промахиваются по дракону; он проходит все спасброски и иммунен к урону и состояниям. Существо может действием распознать иллюзию проверкой Интеллекта (Расследование) против Сл заклинаний; после успеха оно видит сквозь дракона и получает преимущество на спасброски от дыхания.' where slug='illusory-dragon' and source_kind='official';

update public.spell_catalog set name_ru='Безумная тьма', effect_summary='Создаёшь сферу магической тьмы радиусом 60 футов в точке в пределах 150 футов на срок до 10 минут с концентрацией. Тёмное зрение не позволяет видеть сквозь неё. Существо, начинающее ход внутри сферы, делает спасбросок Мудрости, получая 8к8 психического урона при провале или половину при успехе.', author_description='Огромная область, которая одновременно выключает видимость и каждую секунду давит на разум тех, кто остался внутри.', author_comment='Обычная тьма скрывает опасность. Эта решила сама быть опасностью.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Магический свет, созданный заклинанием 8 уровня или ниже, не может осветить эту область. Материальный компонент — капля смолы, смешанная с каплей ртути; не расходуется.', material='капля смолы, смешанная с каплей ртути — не расходуется', material_cost_gp=null, material_consumed=false, material_consumption='none' where slug='maddening-darkness' and source_kind='official';

update public.spell_catalog set name_ru='Могучая крепость', effect_summary='За 1 минуту поднимаешь из земли каменную крепость на участке 120×120 футов в пределах 1 мили. Она включает четыре башни, стены, трёхэтажный донжон, выбранную тобой внутреннюю планировку, мебель, пищу для роскошного ежедневного пира до 100 существ и сотню невидимых слуг, выполняющих команды назначенных тобой существ.', author_description='Не убежище и не домик — полноценная военная крепость со стенами, персоналом и снабжением, появляющаяся почти мгновенно.', author_comment='Когда «разбить лагерь» звучит недостаточно амбициозно, волшебник достаёт алмаз.', upcast='Не усиливается ячейкой более высокого уровня. Сотворение в одной и той же точке раз в 7 дней в течение года делает крепость постоянной.', notes='Через 7 дней либо когда ты создаёшь такую крепость в другом месте, предыдущая безопасно уходит обратно в землю. Алмаз стоимостью не менее 500 зм расходуется.', casting_time='1 минута', material='алмаз стоимостью не менее 500 зм — расходуется', material_cost_gp=500, material_consumed=true, material_consumption='always' where slug='mighty-fortress' and source_kind='official';

update public.spell_catalog set name_ru='Разрыв реальности', effect_summary='Одно видимое существо в пределах 60 футов делает спасбросок Мудрости. При провале на срок до 1 минуты с концентрацией оно не может совершать реакции, а в начале каждого своего хода случайный разрыв реальности поражает его: психический урон и Оглушение, силовой взрыв, пространственный перенос с падением ничком либо холод и временная Слепота — эффект определяется броском к10.', author_description='Один дебафф превращается в новую катастрофу каждый ход. Цель знает только одно: реальность снова сломается в начале её следующего хода.', author_comment='Хорошее заклинание для тех, кто считает обычную таблицу случайных эффектов слишком стабильной.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='В конце каждого своего хода цель повторяет спасбросок Мудрости и при успехе завершает заклинание. Возможные эффекты наносят 6к12 психического, 8к12 силового, 10к12 силового после телепортации либо 10к12 холода в зависимости от броска к10.', material='кристаллическая призма — не расходуется', material_cost_gp=null, material_consumed=false, material_consumption='none' where slug='reality-break' and source_kind='official';

commit;
